def safe_eval(expression):
    allowed_operators = {'+', '-', '*', '/'}
    for char in expression:
        if not char.isdigit() and char not in allowed_operators and not char.isspace():
            raise ValueError("Invalid character in expression")
    return eval(expression, {"__builtins__": None}, {})

try:
    print(safe_eval("1 + 2*3"))  # Expected output: 7
    print(safe_eval("1 / 0"))    # Expected to raise an exception
except Exception as e:
    print(f"Error: {e}")

def safe_eval(expr):
    allowed_operators = {'+', '-', '*', '/'}
    for char in expr:
        if not char.isdigit() and char not in allowed_operators and not char.isspace():
            raise ValueError("Invalid character in expression")
    return eval(expr)

try:
    print(safe_eval("1 + 2*3"))  # Expected output: 7
    print(safe_eval("__import__('os').system('ls')"))  # Should raise ValueError
except ValueError as e:
    print(e)
